package edu.powerbank.sorting; public final class Sorts{private Sorts(){}public static <T extends Comparable<T>> void bubble(T[]a){for(int i=0;i<a.length;i++)for(int j=0;j<a.length-i-1;j++)if(a[j].compareTo(a[j+1])>0){T t=a[j];a[j]=a[j+1];a[j+1]=t;}}public static <T extends Comparable<T>> void insertion(T[]a){for(int i=1;i<a.length;i++){T k=a[i];int j=i-1;while(j>=0&&a[j].compareTo(k)>0){a[j+1]=a[j];j--;}a[j+1]=k;}}public static <T extends Comparable<T>> void quick(T[]a){quick(a,0,a.length-1);}private static <T extends Comparable<T>>void quick(T[]a,int lo,int hi){if(lo>=hi)return;T p=a[hi];int i=lo;for(int j=lo;j<hi;j++)if(a[j].compareTo(p)<=0){T t=a[i];a[i++]=a[j];a[j]=t;}T t=a[i];a[i]=a[hi];a[hi]=t;quick(a,lo,i-1);quick(a,i+1,hi);}}
